const wc = $('When Called').first().json;
const key = (((($input.first() || {}).json) || {}).key || '').toString().trim();
function parseMaybe(v, fb){ try { return typeof v === 'string' ? JSON.parse(v || fb) : (v != null ? v : JSON.parse(fb)); } catch (e) { return JSON.parse(fb); } }
const tin = parseMaybe(wc.tool_input_json, '{}') || {};
const fmapRaw = parseMaybe(wc.file_map_json, '[]');
const fmap = Array.isArray(fmapRaw) ? fmapRaw : [];
const byId = {};
for (const f of fmap) { if (!f) continue; if (f.file_id) byId[f.file_id] = f; if (f.source_ref) byId[f.source_ref] = f; if (f.url) byId[f.url] = f; }
const prompt = (tin.prompt != null ? String(tin.prompt) : '').trim();
const refIds = Array.isArray(tin.reference_file_ids) ? tin.reference_file_ids : [];
const warnings = [];
const reference_urls = [];
const resolved_refs = [];
for (const id of refIds) {
  const f = byId[id];
  if (f && f.url) { reference_urls.push(f.url); resolved_refs.push(id); }
  else warnings.push({ source: 'image-tool/reference-not-found', err: 'reference_file_id ' + id + ' not in session file map; generating without that reference', severity: 'WARN' });
}
let count = Number(tin.count != null ? tin.count : 1);
if (!count || isNaN(count) || count < 1) count = 1;
if (count > 4) { warnings.push({ source: 'image-tool/count-clamped', err: 'requested count ' + tin.count + ' clamped to 4', severity: 'WARN' }); count = 4; }
const size = (tin.size != null && String(tin.size).trim() !== '') ? String(tin.size).trim() : null;
const aspect = (tin.aspect_ratio != null && String(tin.aspect_ratio).trim() !== '') ? String(tin.aspect_ratio).trim() : null;
const requests = [];
for (let i = 0; i < count; i++) {
  requests.push({ placeholder_id: 'gen_' + i, prompt: prompt, block_order: i, size: size, aspect: aspect, reference_urls: reference_urls });
}
if (!prompt) warnings.push({ source: 'image-tool/no-prompt', err: 'generate_image called with empty prompt', severity: 'WARN' });
if (!key) warnings.push({ source: 'image-tool/key-unreachable', err: 'anthropic key not reachable from Vault; cannot upload generated images', severity: 'WARN' });
const do_generate = !!key && !!prompt && requests.length > 0;
return [{ json: {
  key: key,
  requests_json: JSON.stringify(requests),
  impact: wc.impact || '__default__',
  concurrency_cap: (wc.concurrency_cap != null && Number(wc.concurrency_cap) > 0) ? Number(wc.concurrency_cap) : 4,
  clickup_task_id: wc.clickup_task_id || '',
  triggered_by: wc.triggered_by || 'image_gen',
  invocation_type: wc.invocation_type || 'explicit',
  caller_user_id: wc.caller_user_id || '',
  process_type: wc.process_type || '',
  do_generate: do_generate,
  no_prompt: !prompt,
  key_missing: !key,
  count_requested: count,
  ref_resolved_count: reference_urls.length,
  warnings: warnings
} }];

return $input.all().map(function(i){
  const e = i.json || {};
  return { json: {
    placeholder_id: e.placeholder_id || '',
    success: !!(e.success && e.b64_json),
    b64_json: e.b64_json || null,
    mime: e.mime || 'image/png',
    used_reference: !!e.used_reference,
    model: e.model || '',
    size: e.size || null,
    caption: e.caption || '',
    alt: e.alt || '',
    error: e.error || '',
    batch_warnings: Array.isArray(e.warnings) ? e.warnings : []
  } };
});

const meta = $('Normalize Batch Output').item.json;
const up = $json || {};
return { json: {
  ok: true,
  file_id: up.id || null,
  b64_json: meta.b64_json,
  mime: up.mime_type || meta.mime || 'image/png',
  used_reference: !!meta.used_reference,
  placeholder_id: meta.placeholder_id,
  caption: meta.caption || '',
  alt: meta.alt || '',
  batch_warnings: Array.isArray(meta.batch_warnings) ? meta.batch_warnings : []
} };

const meta = $('Normalize Batch Output').item.json;
const e = $json || {};
const err = (e.error && (e.error.message || e.error)) || e.message || 'upload_failed';
return { json: { ok: false, kind: 'upload', placeholder_id: meta.placeholder_id, err: String(err).slice(0, 300), batch_warnings: Array.isArray(meta.batch_warnings) ? meta.batch_warnings : [] } };

const e = ($input.first() && $input.first().json) || {};
const err = (e.error && (e.error.message || e.error)) || e.message || 'image batch threw';
return [{ json: { batch_failed: true, err: String(err).slice(0, 300) } }];

const rows = $input.all().map(function(i){ return i.json; }).filter(Boolean);
const oks = rows.filter(function(r){ return r.ok === true && r.file_id; });
const uploadDrops = rows.filter(function(r){ return r.ok === false && r.kind === 'upload'; });
const genDrops = rows.filter(function(r){ return r.ok === false && r.kind === 'gen'; });
const batchFailedRow = rows.find(function(r){ return r.batch_failed === true; });
const sentinel = rows.find(function(r){ return r.no_work === true; });
let reqMeta = {};
let reqWarnings = [];
try { reqMeta = $('Build Requests').first().json || {}; reqWarnings = Array.isArray(reqMeta.warnings) ? reqMeta.warnings : []; } catch (e) {}
const warnings = [];
for (const w of reqWarnings) warnings.push(w);
for (const d of uploadDrops) warnings.push({ source: 'image-tool/upload-failed', err: 'generated image ' + (d.placeholder_id || '') + ' upload failed: ' + (d.err || 'unknown'), severity: 'WARN' });
for (const d of genDrops) warnings.push({ source: 'image-tool/generation-failed', err: 'image ' + (d.placeholder_id || '') + ' not generated: ' + (d.err || 'unknown'), severity: 'WARN' });
if (batchFailedRow) warnings.push({ source: 'image-tool/batch-threw', err: 'image batch failed: ' + (batchFailedRow.err || 'unknown') + '; no images generated (the batch escalates its own CRITICAL)', severity: 'WARN' });
const seenStrings = {};
for (const r of rows) { if (Array.isArray(r.batch_warnings)) { for (const s of r.batch_warnings) { if (s && !seenStrings[s]) { seenStrings[s] = true; warnings.push({ source: 'image-tool/batch-degrade', err: s, severity: 'WARN' }); } } } }
const carrierDrops = rows.filter(function(r){ return r.carrier_failed === true; });
for (const d of carrierDrops) warnings.push({ source: 'image-tool/carrier-write-failed', err: 'produced image ' + (d.file_id || '') + ' bytes not persisted to delivery storage (' + (d.carrier_err || 'unknown') + '); the agent may reference a file_id that cannot be delivered to ClickUp', severity: 'WARN' });
const file_ids = oks.map(function(r){ return r.file_id; });
const images = oks.map(function(r){ return { file_id: r.file_id, b64_json: r.b64_json, mime: r.mime, used_reference: !!r.used_reference, placeholder_id: r.placeholder_id, caption: r.caption || '', alt: r.alt || '' }; });
const count_requested = (reqMeta.count_requested != null) ? reqMeta.count_requested : (oks.length + genDrops.length + uploadDrops.length);
const count_uploaded = file_ids.length;
const count_failed = Math.max(0, count_requested - count_uploaded);
let status, message;
if (sentinel) {
  status = 'failed';
  message = sentinel.no_prompt
    ? 'Image generation was not attempted: no prompt was provided to generate_image. Tell the user no image could be produced.'
    : 'Image generation was not attempted: the image service credential is unavailable. Proceed without an image and note it could not be generated.';
} else if (count_uploaded === 0) {
  status = 'failed';
  message = 'Image generation failed: no images were produced (' + count_requested + ' attempted). Proceed without the image and tell the user it could not be generated.';
} else if (count_failed > 0) {
  status = 'partial';
  message = 'Generated and uploaded ' + count_uploaded + ' of ' + count_requested + ' image(s). Use these file_ids to embed the images in your output: ' + file_ids.join(', ') + '. ' + count_failed + ' image(s) failed.';
} else {
  status = 'ok';
  message = 'Generated and uploaded ' + count_uploaded + ' image(s). Use these file_ids to embed the images in your output: ' + file_ids.join(', ') + '.';
}
let taskId = '';
try { taskId = $('When Called').first().json.clickup_task_id || ''; } catch (e) {}
return [{ json: { status: status, file_ids: file_ids, images: images, warnings: warnings, message: message, count_requested: count_requested, count_uploaded: count_uploaded, count_failed: count_failed, clickup_task_id: taskId } }];

const e = $('Build OK Entry').item.json;
const j = $json || {};
const err = (j.error && (j.error.message || j.error)) || j.message || 'carrier_write_failed';
return { json: Object.assign({}, e, { carrier_failed: true, carrier_err: String(err).slice(0, 300) }) };
